import Foundation

/// Side-view mouth outlines for the practice sounds (Corpus/practice/articulation-v1.json).
/// Generated by `Tools/chimera` (`subvox-chimera postures`) from Chimera's articulator targets for
/// an adult male vocal tract: a model's target shape, not a measurement of any speaker.
struct ArticulationDiagrams: Decodable {
    struct Sound: Decodable { var posture: String; var rule: String?; var note: Note? }
    enum Note: String, Decodable { case start, approximate }
    struct Point: Decodable, Hashable {
        var x: Double; var y: Double
        init(from decoder: Decoder) throws {
            var c = try decoder.unkeyedContainer()
            x = try c.decode(Double.self); y = try c.decode(Double.self)
        }
    }
    /// One outline per part name, in template cm (x forward, y up).
    typealias Posture = [String: [Point]]

    var version: Int
    var chimeraRev: String
    /// Drawing window [minX, minY, maxX, maxY] in cm, the same for every sound so they line up.
    var view: [Double]
    /// Part names in drawing order.
    var parts: [String]
    var sounds: [String: Sound]
    var withoutDiagram: [String: String]
    var postures: [String: Posture]

    static func key(language: String, ipa: String) -> String { language + ":" + ipa }

    /// The sound's entry and outline, or nil when the sound has no diagram (tones, sounds Chimera
    /// has no target for).
    func diagram(language: String, ipa: String) -> (sound: Sound, posture: Posture)? {
        guard let sound = sounds[Self.key(language: language, ipa: ipa)], let posture = postures[sound.posture] else { return nil }
        return (sound, posture)
    }

    static let bundled: ArticulationDiagrams? = {
        guard let url = Bundle.main.url(forResource: "articulation-v1", withExtension: "json", subdirectory: "Corpus/practice"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(ArticulationDiagrams.self, from: data)
    }()
}
